after.installer=()=>{$$("[data-os]").forEach(b=>b.onclick=()=>{S.os=b.dataset.os;render();});const n=$("#instNow2");if(n)n.onclick=async()=>{if(!deferredPrompt)return;deferredPrompt.prompt();try{await deferredPrompt.userChoice;}catch(e){}deferredPrompt=null;render();};
  if(STANDALONE()){const f=$("#fInst");if(f)f.hidden=true;}};

/* ---------- feuille « Qui vient ? » ---------- */
let DR=null;
function drFrom(type){const s=GR.groupes[type]||GDEF[type];return{adultes:s.adultes,enfants:(s.enfants||[]).map(k=>({age:k.age}))};}
function openWho(){const type=gActive()?GR.actif:null;
  DR={type,...(type?drFrom(type):{adultes:2,enfants:[]}),quand:{...(GR.quand||{mode:"weekend"})},rayon:GR.rayon||20};
  if(DR.quand.mode==="dates"&&(!DR.quand.au||DR.quand.au<today()))DR.quand={mode:"weekend"};
  closeOverlays();
  const v=document.createElement("div");v.id="who";v.innerHTML=`<div class="scrim" data-w="close"></div><div class="sheet" role="dialog" aria-modal="true" aria-labelledby="whoT"></div>`;
  document.body.appendChild(v);document.body.classList.add("locked");document.addEventListener("keydown",escKey);drawWho();
  v.addEventListener("click",whoClick);v.addEventListener("change",whoChange);
  const f=v.querySelector(".sheet button");if(f)f.focus({preventScroll:true});}
function closeWho(){const v=$("#who");if(v)v.remove();if(!$("#menu")){document.body.classList.remove("locked");document.removeEventListener("keydown",escKey);}}
function drawWho(){const sh=$("#who .sheet");if(!sh)return;const sc=sh.scrollTop,t=today(),[wf,wt]=defaultStay(),q=DR.quand;
  const step=(k,n,min,max)=>`<div class="stepper"><button type="button" data-w="step" data-k="${k}" data-d="-1" aria-label="Moins" ${n<=min?"disabled":""}><span>${ic("minus","i-s")}</span></button><output aria-live="polite">${n}</output><button type="button" data-w="step" data-k="${k}" data-d="1" aria-label="Plus" ${n>=max?"disabled":""}><span>${ic("plus","i-s")}</span></button></div>`;
  const per=q.mode==="dates"&&q.du&&q.au?(q.du.slice(0,7)===q.au.slice(0,7)?`${dname(q.du)} ${+q.du.slice(8)} → ${dshort(q.au)}`:`${dshort(q.du)} → ${dshort(q.au)}`):"";
  sh.innerHTML=`<div class="sheet-top"><div class="sheet-grab"></div>
   <div class="sheet-head"><h2 class="sheet-title" id="whoT">Qui vient ?</h2><button type="button" class="icon-btn" data-w="close" aria-label="Fermer" style="margin-right:-10px">${ic("close")}</button></div></div>
   <p class="sheet-sub">On trie sorties, âges et horaires pour vous. Rien ne quitte ce téléphone.</p>
   <div class="field"><span class="field-label">Avec qui</span><div class="chips">${GTYPES.map(([k,l])=>`<button type="button" class="chip" aria-pressed="${DR.type===k}" data-w="type" data-v="${k}">${l}</button>`).join("")}</div></div>
   <div class="field"><span class="field-label">Quand</span><div class="chips">
     <button type="button" class="chip" aria-pressed="${q.mode==="jour"}" data-w="q" data-v="jour">Aujourd'hui</button>
     <button type="button" class="chip" aria-pressed="${q.mode==="weekend"}" data-w="q" data-v="weekend">Ce week-end</button>
     <button type="button" class="chip" aria-pressed="${q.mode==="dates"}" data-w="q" data-v="dates">${ic("cal")}Des dates</button></div>
     ${q.mode==="weekend"?`<p class="sheet-sub" style="margin:8px 0 0">Du ${dlong(wf)} au ${dlong(wt)}</p>`:""}
     ${q.mode==="dates"?`<p class="sheet-sub" style="margin:8px 0 0">${esc(per)}</p><div class="dates"><label>Arrivée<input type="date" id="wDu" value="${q.du||t}" min="${addDays(t,-30)}"></label><label>Départ<input type="date" id="wAu" value="${q.au||addDays(q.du||t,6)}" min="${t}"></label></div>`:""}</div>
   <div class="field" style="padding-bottom:4px">
     <div class="stepper-row"><span class="stepper-label">Adultes</span>${step("adultes",DR.adultes,1,12)}</div>
     <div class="stepper-row"><span class="stepper-label">Enfants<small>${DR.enfants.length?"Leur âge pendant le séjour":"Ajoutez-les pour trier par âge"}</small></span>${step("enfants",DR.enfants.length,0,8)}</div>
     ${DR.enfants.length?`<div class="ages">${DR.enfants.map((k,i)=>`<label class="age">${k.age<1?"moins d'1 an":k.age+" an"+(k.age>1?"s":"")}${ic("down")}<select data-w="age" data-i="${i}" aria-label="Âge de l'enfant ${i+1}">${[...Array(18)].map((_,a)=>`<option value="${a}" ${a===+k.age?"selected":""}>${a<1?"moins d'1 an":a+" an"+(a>1?"s":"")}</option>`).join("")}</select></label>`).join("")}</div>`:""}</div>
   <div class="field"><span class="field-label">Pour sortir</span><div class="seg" role="group" aria-label="Distance">${RAYONS.map(([r,l])=>`<button type="button" aria-pressed="${DR.rayon===r}" data-w="r" data-v="${r}">${l}</button>`).join("")}</div></div>
   <div class="sheet-actions"><button type="button" class="btn btn-primary btn-block" data-w="ok">${DR.quand.mode==="weekend"?"Voir notre week-end":"Voir notre programme"}</button><button type="button" class="btn btn-quiet btn-block" data-w="local">J'habite ici, sans groupe</button></div>`;
  sh.scrollTop=sc;}
function whoClick(e){const b=e.target.closest("[data-w]");if(!b||b.tagName==="SELECT")return;const w=b.dataset.w;
  if(w==="close")return closeWho();
  if(w==="type"){DR.type=b.dataset.v;Object.assign(DR,drFrom(DR.type));}
  else if(w==="q"){const m=b.dataset.v;DR.quand=m==="dates"?{mode:"dates",du:DR.quand.du||today(),au:DR.quand.au||addDays(DR.quand.du||today(),6)}:{mode:m};}
  else if(w==="step"){const d=+b.dataset.d;if(b.dataset.k==="adultes")DR.adultes=Math.max(1,Math.min(12,DR.adultes+d));
    else if(d>0&&DR.enfants.length<8)DR.enfants.push({age:DR.enfants.length?Math.max(0,DR.enfants[DR.enfants.length-1].age-3):8});else if(d<0)DR.enfants.pop();}
  else if(w==="r")DR.rayon=+b.dataset.v;
  else if(w==="ok"){let q=DR.quand;if(q.mode==="dates"){let a=q.du||today(),z=q.au||a;if(z<a)[a,z]=[z,a];if(z<today()){toast("Ces dates sont passées");return;}q={mode:"dates",du:a,au:z};}
    if(!DR.type)DR.type=DR.enfants.length?"famille":DR.adultes>=3?"amis":DR.adultes===2?"couple":"solo";
    GR.groupes[DR.type]={nom:(GTYPES.find(x=>x[0]===DR.type)||[])[1]||"",adultes:DR.adultes,enfants:DR.enfants.map(k=>({age:+k.age})),type:DR.type};
    GR.actif=DR.type;GR.habitant=false;GR.quand=q;GR.rayon=DR.rayon;gSave();
    S.day=null;S.who="groupe";S.where=DR.rayon<=1.5?"ici":DR.rayon<=10?"10":"20";closeWho();
    if(curView()!=="sejour")location.hash="#sejour";else{render();window.scrollTo({top:0,behavior:"instant"});}return;}
  else if(w==="local"){GR.habitant=true;GR.actif=null;gSave();S.who="tous";S.day=null;closeWho();if(curView()!=="sejour")location.hash="#sejour";else render();return;}
  drawWho();}
function whoChange(e){const el=e.target;
  if(el.dataset.w==="age"){DR.enfants[+el.dataset.i].age=+el.value;drawWho();}
  else if(el.id==="wDu"&&el.value){DR.quand.du=el.value;if(!DR.quand.au||DR.quand.au<el.value)DR.quand.au=addDays(el.value,6);drawWho();}
  else if(el.id==="wAu"&&el.value){DR.quand.au=el.value;drawWho();}}

/* ---------- menu (bouton en haut à droite) ---------- */
const MENU1=[["sejour","Aujourd'hui","Marée, sorties et ciné du jour","home"],["agenda","Agenda","Fêtes, lotos, concerts, brocantes","cal"],["cine","Ciné","L'Atlantique et les cinémas voisins","film"],["mer","Marées et mer","Horaires, coefficients, surf et vent","tide"],["manger","Manger","Restos, huîtres, marchés, boulangeries","fork"],["activites","À faire","Sorties, sport, nature, associations","compass"]];
const MENU2=[["pratique","Urgences et numéros utiles","112 · 15 · 18 · 196 en mer · pharmacie 3237","phone"],["peche","Pêche à pied","Bonnes marées, créneau conseillé, sécurité","shell"],["venir","Cars et trains","","bus"],["recherche","Rechercher","","search"],["apropos","À propos et contact","","info"]];
function themeNow(){const t=sget("pp-theme");return t==="light"||t==="dark"?t:"auto";}
function setTheme(v){const r=document.documentElement;if(v==="auto"){r.removeAttribute("data-theme");try{localStorage.removeItem("pp-theme")}catch(e){}}else{r.setAttribute("data-theme",v);sset("pp-theme",v);}}
function closeOverlays(){const m=$("#menu");if(m)m.remove();const w=$("#who");if(w)w.remove();document.body.classList.remove("locked");document.removeEventListener("keydown",escKey);}
function escKey(e){if(e.key==="Escape"){const had=$("#menu");closeOverlays();if(had){const mb=$("#menuBtn");if(mb)mb.focus({preventScroll:true});}}}
function openMenu(){closeOverlays();const c=curView(),g=gActive();
  const it=([h,l,t,i])=>`<li><a class="menu-item" href="#${h}" ${h===c?'aria-current="page"':""}>${ic(i)}<span><b>${l}</b>${t?`<small>${t}</small>`:""}</span></a></li>`;
  const v=document.createElement("div");v.id="menu";v.className="menu";v.setAttribute("role","dialog");v.setAttribute("aria-modal","true");v.setAttribute("aria-label","Menu");
  v.innerHTML=`<div class="menu-in"><div class="menu-head"><a class="brand" href="#sejour">${ic("brand")}Le Petit Préf</a><button type="button" class="menu-btn" data-m="close">${ic("close")}Fermer</button></div>
   <div class="group-card"><span class="ctx-ic">${ic("people","i-s")}</span><div class="ctx-main">${g?`<div class="ctx-who">${esc(gWho(g,GR.actif))}</div><div class="ctx-when">${esc(gWhen())}</div>`:`<div class="ctx-who">${GR.habitant?"J'habite ici":"Qui vient ?"}</div><div class="ctx-when">${GR.habitant?"Accueil sans groupe ni dates":"Famille, amis, dates : on trie pour vous"}</div>`}</div><button type="button" class="ctx-edit" data-m="who">${g?"Modifier":"Choisir"}</button></div>
   <p class="menu-group">Rubriques</p><ul class="menu-list">${MENU1.map(it).join("")}</ul>
   <p class="menu-group">Pratique</p><ul class="menu-list">${MENU2.map(it).join("")}</ul>
   <p class="menu-group">Affichage</p><div style="margin:0 var(--gutter)"><div class="seg" role="group" aria-label="Thème">${[["auto","Auto"],["light","Clair"],["dark","Sombre"]].map(([k,l])=>`<button type="button" aria-pressed="${themeNow()===k}" data-m="theme" data-v="${k}">${l}</button>`).join("")}</div></div>
   ${STANDALONE()?"":`<a class="invite" href="#installer" style="display:flex;gap:12px;align-items:center;margin-top:22px;margin-bottom:8px;min-height:56px">${ic("install")}<span style="flex:1"><span class="invite-title" style="display:block">Installer l'app</span><span class="row-meta">Une icône sur l'écran d'accueil, sans store.</span></span>${ic("chev","i-s dim")}</a>`}
  </div>`;
  v.addEventListener("click",e=>{const b=e.target.closest("[data-m]");
    if(b){const m=b.dataset.m;if(m==="close"){closeOverlays();const mb=$("#menuBtn");if(mb)mb.focus({preventScroll:true});}
      else if(m==="who"){closeOverlays();openWho();}
      else if(m==="theme"){setTheme(b.dataset.v);v.querySelectorAll("[data-m=theme]").forEach(x=>x.setAttribute("aria-pressed",x.dataset.v===b.dataset.v));}return;}
    if(e.target.closest("a"))closeOverlays();});
  document.addEventListener("keydown",escKey);
  document.body.appendChild(v);document.body.classList.add("locked");
  const f=v.querySelector("[data-m=close]");if(f)f.focus({preventScroll:true});}
{const mb=document.getElementById("menuBtn");if(mb)mb.onclick=openMenu;}

/* ---------- actions des vues (délégation) ---------- */
const ACT={
  who:()=>openWho(),
  local:()=>{GR.habitant=true;gSave();render();toast("Noté. « Qui vient ? » reste dans le menu.");},
  day:v=>{S.day=v;render();},
  pluie:v=>{GR.pluie=v==="1";gSave();render();},
  when:v=>{S.when=v;S.more={};if(curView()==="agenda")render();},
  cin:v=>{S.cin=v;sset("pp-cin",v);S.cineDay=null;if(curView()==="cine")render();},
  cday:v=>{S.cineDay=v;if(curView()==="cine")render();},
  open:()=>{S.openToday=true;S.rain=false;S.cat="tous";},
  rain:()=>{S.rain=true;S.openToday=false;S.cat="tous";},
  grp:()=>{S.who="groupe";S.cat="tous";},
  eat:()=>{S.openToday=true;S.mk="tous";},
  free:()=>{S.free=!S.free;render();},
  openT:()=>{S.openToday=!S.openToday;render();},
  rainT:()=>{S.rain=!S.rain;render();},
  mk:v=>{S.mk=v;render();},
  av:v=>{S.actView=v;render();},
  more:v=>{S.more[v]=true;render();},
  tday:v=>{S.tideDay=v;render();},
  reset:()=>{S.when="tout";S.etype="tous";S.free=false;S.who="tous";S.where="tout";S.cat="tous";S.rain=false;S.openToday=false;S.mk="tous";render();},
  kml:()=>{const st=$("#kmlStatus");
    try{const u=URL.createObjectURL(new Blob([kml()],{type:"application/vnd.google-earth.kml+xml"}));const a=document.createElement("a");a.href=u;a.download="lepetitpref-carte.kml";document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),4000);
      if(st)st.textContent="Fichier enregistré. Sur mymaps.google.com : Créer une carte → Importer → ce fichier. La carte apparaît ensuite dans Google Maps, onglet « Enregistrés ».";
    }catch(e){if(st)st.textContent="Téléchargement annulé.";}}};
const CHG={etype:v=>{S.etype=v;},where:v=>{S.where=v;sset("cf-where",v);},who:v=>{S.who=v;},cat:v=>{S.cat=v;},tday:v=>{if(v)S.tideDay=v;}};
document.addEventListener("click",e=>{const el=e.target.closest("[data-act]");if(!el||!el.closest("#main"))return;
  const f=ACT[el.dataset.act];if(!f)return;if(el.tagName==="BUTTON")e.preventDefault();f(el.dataset.v,el,e);});
document.addEventListener("change",e=>{const el=e.target.closest("[data-chg]");if(!el||!el.closest("#main"))return;const f=CHG[el.dataset.chg];if(f){f(el.value);render();}});
document.addEventListener("click",e=>{const g=e.target.closest("#main [data-poi]");if(!g)return;S.selPoi=+g.dataset.poi;render();});
document.addEventListener("keydown",e=>{const g=e.target.closest&&e.target.closest("#main [data-poi]");if(g&&e.key==="Enter"){e.preventDefault();S.selPoi=+g.dataset.poi;render();}});

/* ---------- rendu et navigation ---------- */
function curView(){const h=location.hash.slice(1);return VIEWS.some(v=>v[0]===h)||EXTRA.includes(h)?h:"sejour";}
const PARENT={cine:"agenda",pratique:"sejour",venir:"sejour",peche:"mer"};
function rail(){const c=curView(),p=PARENT[c]||c,r=$("#rail");if(!r)return;r.innerHTML=VIEWS.map(([id,l])=>`<a class="tab" href="#${id}" ${id===p?'aria-current="page"':""}>${l}</a>`).join("");}
document.addEventListener("click",e=>{const a=e.target.closest("#rail a");if(!a)return;if(a.getAttribute("href")==="#"+curView()){e.preventDefault();window.scrollTo({top:0,behavior:"smooth"});}});
const TITLES={recherche:"Rechercher",apropos:"À propos",installer:"Installer",venir:"Cars et trains",cine:"Ciné",pratique:"Pratique",peche:"Pêche à pied"};

function render(){rail();const v=curView();document.title=v==="sejour"?"Le Petit Préf":(VIEWS.find(x=>x[0]===v)?.[1]||TITLES[v])+" · Le Petit Préf";
  const keep={},fo=document.activeElement&&document.activeElement.id;
  $$("#main form input,#main form select,#main form textarea,#q").forEach(el=>{if(el.id)keep[el.id]=el.type==="checkbox"?el.checked:el.value;});
  const open=[...$$("#main details[open] summary .row-title")].map(x=>x.textContent);
  const sy=window.scrollY;
  $("#main").innerHTML=`<section class="view">${({sejour:vSejour,agenda:vAgenda,cine:vCine,activites:vActs,manger:vManger,mer:vMer,venir:vVenir,recherche:vSearch,apropos:vApropos,installer:vInstaller,pratique:vPratique,peche:vPeche})[v]()}</section>`;
  if(open.length)$$("#main details summary .row-title").forEach(x=>{if(open.includes(x.textContent))x.closest("details").open=true;});
  for(const[id,val]of Object.entries(keep)){const el=document.getElementById(id);if(!el)continue;if(el.type==="checkbox")el.checked=val;else el.value=val;}
  if(fo){const el=document.getElementById(fo);if(el&&(el.closest("form")||el.id==="q"))el.focus({preventScroll:true});}
  window.scrollTo({top:sy,behavior:"instant"});
  after[v]&&after[v]();}
after.sejour=()=>bindInstall();

/* ---------- nouvelle version du site ---------- */
(function(){const vPage=(document.querySelector('meta[name="pp-version"]')||{}).content,t0=Date.now(),reload=/[?&]maj=/.test(location.search);let vu=0,touche=false;
  ["pointerdown","keydown","scroll"].forEach(e=>addEventListener(e,()=>{touche=true;},{once:true,passive:true}));
  const go=v=>location.replace(location.pathname+"?maj="+v+location.hash);
  function check(){if(!vPage||Date.now()-vu<60000||document.getElementById("pp-maj"))return;vu=Date.now();
    fetch("donnees/version.json?t="+Date.now(),{cache:"no-store"}).then(r=>r.ok?r.json():null).then(o=>{
      if(!o||!o.v||o.v===vPage||document.getElementById("pp-maj"))return;let deja=null;try{deja=sessionStorage.getItem("pp-maj-auto");}catch(e){}
      if(!touche&&!reload&&Date.now()-t0<4000&&deja!==o.v){try{sessionStorage.setItem("pp-maj-auto",o.v);}catch(e){}go(o.v);return;}
      const b=document.createElement("button");b.type="button";b.id="pp-maj";b.className="pp-maj";b.innerHTML="<span>Une nouvelle version du Petit Préf est en ligne.</span><b>Mettre à jour</b>";
      b.onclick=()=>{b.disabled=true;go(o.v);};document.body.appendChild(b);}).catch(()=>{});}
  if(reload)try{history.replaceState(null,"",location.pathname+location.hash);}catch(e){}
  check();document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")check();});addEventListener("focus",check);
})();

/* ---------- démarrage ---------- */
const POS={};let lastView=curView();
window.addEventListener("hashchange",()=>{const v=curView();
  if(!VIEWS.some(x=>x[0]===v)&&!EXTRA.includes(v)){const el=document.getElementById(location.hash.slice(1));if(el)el.scrollIntoView({behavior:"smooth",block:"start"});return;}
  closeOverlays();
  POS[lastView]=window.scrollY;lastView=v;
  const go=()=>{render();window.scrollTo({top:POS[v]||0,behavior:"instant"});};
  if(document.startViewTransition&&!matchMedia("(prefers-reduced-motion: reduce)").matches)document.startViewTransition(go);
  else{go();const w=$("#main .view");if(w){w.classList.add("enter");setTimeout(()=>w.classList.remove("enter"),260);}}});
render();
(async()=>{
  const get=n=>fetch(`donnees/${n}.json`,{cache:"no-cache"}).then(r=>{if(!r.ok)throw new Error(n);return r.json();});
  const names=["events","cinema","assos"];
  const res=await Promise.allSettled([...names.map(get),get("status")]);
  names.forEach((n,k)=>{S[n]=res[k].status==="fulfilled"?res[k].value:[];});
  const st=res[names.length];S.meta=st.status==="fulfilled"?st.value:null;
  if(res.every(r=>r.status==="rejected"))S.err="Les données ne se chargent pas. Vérifiez la connexion puis rechargez la page.";
  if(S.meta?.updatedAt){const u=$("#upd");if(u)u.textContent="Agenda et cinéma mis à jour le "+F(new Date(S.meta.updatedAt),{day:"numeric",month:"long",hour:"2-digit",minute:"2-digit"})+".";}
  render();
})();
if("serviceWorker" in navigator&&location.protocol==="https:")navigator.serviceWorker.register("sw.js").catch(()=>{});
